-- Part 6 (diversification pass): MCQ top-up for planning_engineer. This role was sitting at
-- exactly 30 questions (the original seeding floor). Adds 24 further questions on topics NOT
-- already covered by mcq_part5_planning_engineer_seed.sql (verified by diffing topic lists):
-- free float definition, lead/lag, resource leveling vs smoothing, progress measurement rules
-- of credit, schedule risk analysis (Monte Carlo), PERT three-point estimate calculation,
-- critical-chain buffers, milestone weighting. Domain grounding: PMBOK/CPM scheduling theory,
-- PERT statistics, resource-constrained scheduling practice.
-- Same rotation technique as supabase/seed/mcq_questions_seed.sql. Idempotent via
-- (job_role, md5(stem_fa)) unique index.

insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, explanation_fa, standard_ref, approval_status, active)
select 'planning_engineer', x ->> 0, x ->> 1, (x ->> 2)::smallint, x ->> 3,
  (select jsonb_agg(x -> 4 -> ((i - r.k + 4) % 4) order by i) from generate_series(0, 3) i),
  ((n - 1) % 4)::smallint, x ->> 6, x ->> 7, 'APPROVED', true
